insert into financial_test_results select lives_ok($$select public.create_admin_financial_entry('manual',null,'income',500,'Pendente',null,'2030-01-01','pending')$$,'pending entry');
insert into financial_test_results select is(public.get_admin_financial_summary('2030-01-01'),'{"income":"100.00","expense":"30.00","balance":"70.00"}'::jsonb,'paid only contributes to whole-month summary');
insert into financial_test_results select throws_ok($$select public.create_admin_financial_entry('manual',null,'income',0,null,null,'2030-01-01','paid')$$,'22023','financial_invalid','zero rejected');
insert into financial_test_results select throws_ok($$select public.create_admin_financial_entry('manual',null,'expense',-1,null,null,'2030-01-01','paid')$$,'22023','financial_invalid','negative rejected');
