insert into financial_test_results select throws_ok($$select public.complete_admin_sale((select id from public.sales where customer_name='Venda teste'))$$,'55000','sale_already_completed','double completion blocked');
insert into financial_test_results select is((select count(*) from public.financial_entries where source_type='sale'),1::bigint,'no duplicate receipt');
