insert into financial_test_results select is((select status::text from public.appointments where id='ee640000-0000-4000-8000-000000000001'),'scheduled','payment leaves operational status');
insert into financial_test_results select throws_ok($$select public.create_admin_financial_entry('appointment','ee640000-0000-4000-8000-000000000001','income',60,null,null,'2030-01-01','paid')$$,'23505',null,'duplicate appointment payment blocked');
insert into financial_test_results select lives_ok($$select public.create_admin_financial_entry('appointment','ee640000-0000-4000-8000-000000000002','income',80,'Reserva',null,'2030-01-01','pending')$$,'combined resolves reservation');
