insert into financial_test_results select throws_ok($$insert into public.financial_entries(business_id,entry_type,amount,entry_date,source_type,source_id,status) values('be640000-0000-4000-8000-000000000001','income',5,'2030-01-01','appointment','ee640000-0000-4000-8000-000000000003','paid')$$,'23514','financial_appointment_invalid','database independently rejects cross-tenant appointment origin');
