insert into financial_test_results select is((select status from public.financial_entries where source_type='reservation'),'pending','operational completion does not mark payment paid');
insert into financial_test_results select lives_ok($$select public.save_admin_sale_draft(null,'Zero','pix','[{"product_id":"de640000-0000-4000-8000-000000000001","quantity":1,"unit_price":0}]')$$,'zero-price draft retained');
insert into financial_test_results select throws_ok($$select public.complete_admin_sale((select id from public.sales where customer_name='Zero'))$$,'23514','sale_positive_total_required','zero total fails clearly before ledger writes');
insert into financial_test_results select is((select count(*) from public.financial_entries),0::bigint,'tenant isolation');
insert into financial_test_results select is((select count(*) from public.financial_entries),0::bigint,'management false hides data');
insert into financial_test_results select throws_ok($$select public.create_admin_financial_entry('manual',null,'income',1,null,null,'2030-01-01','paid')$$,'42501','financial_unauthorized','management false blocks mutation');
insert into financial_test_results select throws_ok($$select public.get_admin_financial_summary('2030-01-01')$$,'42501','financial_unauthorized','management false blocks summary');
insert into financial_test_results select ok(not has_table_privilege('anon','public.financial_entries','SELECT,INSERT,UPDATE,DELETE'),'anon has no grants');
insert into financial_test_results select ok(not has_table_privilege('authenticated','public.financial_entries','INSERT,UPDATE,DELETE'),'client mutations only via RPC');
insert into financial_test_results select * from finish();
