begin;
create extension if not exists pgtap with schema extensions;
create temp table financial_test_results(result text);
grant select,insert on financial_test_results to authenticated,anon;
update public.business_modules set enabled=true where module='management' and business_id in ('be640000-0000-4000-8000-000000000001','be640000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae640000-0000-4000-8000-000000000001","role":"authenticated"}',true);
-- Synthetic failure after stock insert proves transaction rollback. Trigger exists only inside this test transaction.
reset role;
create function pg_temp.reject_test_finance() returns trigger language plpgsql as $$begin raise exception 'test_financial_failure' using errcode='P0001'; end;$$;
create trigger test_financial_failure before insert on public.financial_entries for each row execute function pg_temp.reject_test_finance();
set local role authenticated;
reset role;
drop trigger test_financial_failure on public.financial_entries;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae640000-0000-4000-8000-000000000002","role":"authenticated"}',true);
reset role;
update public.business_modules set enabled=false where business_id='be640000-0000-4000-8000-000000000001' and module='management';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae640000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
select result from financial_test_results;
rollback;
